using Archy.Features.Placement.ComputeModuleCohesion; using Archy.Features.Graph.CommitGraphRevision; using Archy.Features.Graph.ReadGraphRevision;
namespace Archy.UnitTests.Features.Placement.ComputeModuleCohesion;
public sealed class ModuleCohesionCalculatorTests { [Fact] public void CalculateReportsHigherCohesionForTheMoreInternallyConnectedModule(){var nodes=new[]{Node("a"),Node("b"),Node("c"),Node("d")};var edges=new[]{Edge("a","b",1),Edge("c","d",.2),Edge("b","c",.5)};var r=new ModuleCohesionCalculator().Calculate(new GraphRevisionSnapshot(4,nodes,edges,[],[]),[new("left",["a","b"]),new("right",["c","d"])],"2.0.2");Assert.True(r.Metrics.Single(x=>x.CommunityKey=="left").Cohesion>r.Metrics.Single(x=>x.CommunityKey=="right").Cohesion);Assert.Equal("louvain",r.ClusterRevision.Algorithm);} static GraphNodeFact Node(string id)=>new(id,"method",id,id,$"{id}.cs",1,2,"test",1,"{}","hash");static GraphEdgeFact Edge(string a,string b,double c)=>new($"{a}-{b}",a,b,"calls",null,"test",c,"{}"); }
